import {
  existsSync,
  lstatSync,
  readFileSync,
  readdirSync,
  readlinkSync,
  realpathSync,
} from "node:fs";
import { createHash } from "node:crypto";
import { homedir } from "node:os";
import { dirname, join, parse, resolve } from "node:path";
import { getConfigPath } from "./paths.js";
import { assertBackgroundArgvDurable } from "./background-command-argv.js";

export const BACKGROUND_LAUNCH_PROFILE_VERSION = 1;

const PERMISSION_MODES = new Set([
  "manual",
  "auto",
  "dontAsk",
  "default",
  "plan",
  "acceptEdits",
  "bypassPermissions",
]);
const SANDBOX_MODES = new Set(["off", "workspace-write", "strict"]);
const TRI_STATES = new Set(["auto", "enabled", "disabled"]);
const PERMISSION_RANK = new Map([
  ["plan", 0],
  ["manual", 1],
  ["default", 1],
  ["dontAsk", 2],
  ["acceptEdits", 3],
  ["auto", 4],
  ["bypassPermissions", 5],
]);

function scalar(value, max = 1024) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text ? text.slice(0, max) : null;
}

function positive(value, integer = false) {
  if (value === null || value === undefined || value === "") return null;
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) return null;
  return integer ? Math.floor(number) : number;
}

function invalidProfileField(field) {
  const error = new Error(`Invalid background launch profile field: ${field}`);
  error.code = "BACKGROUND_LAUNCH_PROFILE_INVALID";
  return error;
}

function policyBudget(value, field) {
  const text = String(value).trim();
  const cost = field.toLowerCase().includes("cost");
  const number = Number(value);
  if (
    value == null ||
    !(cost ? /^\+?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i : /^\+?\d+$/).test(
      text,
    ) ||
    !Number.isFinite(number) ||
    number <= 0 ||
    (!cost && !Number.isSafeInteger(number))
  )
    throw invalidProfileField(`budget.${field}`);
  return number;
}

function sortedStrings(values, { split = false, pathsFrom = null } = {}) {
  const raw = Array.isArray(values) ? values : values ? [values] : [];
  const expanded = split
    ? raw.flatMap((value) => String(value).split(/[\s,]+/))
    : raw;
  return [
    ...new Set(
      expanded
        .map((value) => scalar(value, 4096))
        .filter(Boolean)
        .map((value) => (pathsFrom ? resolve(pathsFrom, value) : value)),
    ),
  ].sort();
}

function orderedStrings(values, { split = false } = {}) {
  const raw = Array.isArray(values) ? values : values ? [values] : [];
  const expanded = split
    ? raw.flatMap((value) => String(value).split(/[\s,]+/))
    : raw;
  return [
    ...new Set(expanded.map((value) => scalar(value, 4096)).filter(Boolean)),
  ];
}

function canonicalPath(value, cwd) {
  const absolute = resolve(cwd || process.cwd(), String(value || ""));
  try {
    return realpathSync.native
      ? realpathSync.native(absolute)
      : realpathSync(absolute);
  } catch {
    return absolute;
  }
}

function hashPathEntry(hash, absolute, relative = ".") {
  const stat = lstatSync(absolute);
  if (stat.isSymbolicLink()) {
    hash.update(`link\0${relative}\0${readlinkSync(absolute)}\0`);
    return;
  }
  if (stat.isDirectory()) {
    hash.update(`dir\0${relative}\0`);
    for (const name of readdirSync(absolute).sort()) {
      hashPathEntry(hash, join(absolute, name), `${relative}/${name}`);
    }
    return;
  }
  if (stat.isFile()) {
    hash.update(`file\0${relative}\0${stat.size}\0`);
    hash.update(readFileSync(absolute));
    hash.update("\0");
    return;
  }
  hash.update(`other\0${relative}\0${stat.mode}\0${stat.size}\0`);
}

/**
 * Describe a configuration input without storing its contents. The digest is
 * deliberately content-addressed (rather than mtime-addressed), so touching a
 * file does not make a compatible background session impossible to resume.
 */
export function describeBackgroundConfigSource(path, options = {}) {
  const absolute = canonicalPath(path, options.cwd);
  if (!existsSync(absolute)) {
    return { path: absolute, kind: "missing", sha256: null };
  }
  try {
    const stat = lstatSync(absolute);
    const kind = stat.isDirectory()
      ? "directory"
      : stat.isFile()
        ? "file"
        : stat.isSymbolicLink()
          ? "symlink"
          : "other";
    const hash = createHash("sha256");
    hashPathEntry(hash, absolute);
    return { path: absolute, kind, sha256: hash.digest("hex") };
  } catch {
    // Never serialize an exception message: filesystem errors can include
    // credential-bearing paths supplied by external configuration.
    return { path: absolute, kind: "unavailable", sha256: null };
  }
}

function findAncestorFile(cwd, ...parts) {
  let current = resolve(cwd || process.cwd());
  const root = parse(current).root;
  for (let depth = 0; depth < 64; depth++) {
    const candidate = join(current, ...parts);
    if (existsSync(candidate)) return candidate;
    if (current === root) break;
    const parent = dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return null;
}

function findGitRoot(cwd) {
  const marker = findAncestorFile(cwd, ".git");
  return marker ? dirname(marker) : null;
}

function sourceList({ cwd, settingsFile, mcpConfig, bundle, projectMcp }) {
  const files = [getConfigPath()];
  const gitRoot = findGitRoot(cwd);
  const projectConfig = findAncestorFile(cwd, ".chainlesschain", "config.json");
  files.push(
    projectConfig || join(gitRoot || cwd, ".chainlesschain", "config.json"),
  );

  files.push(join(homedir(), ".claude", "settings.json"));
  if (gitRoot && canonicalPath(gitRoot) !== canonicalPath(cwd)) {
    files.push(join(gitRoot, ".claude", "settings.json"));
    files.push(join(gitRoot, ".claude", "settings.local.json"));
  }
  files.push(join(cwd, ".claude", "settings.json"));
  files.push(join(cwd, ".claude", "settings.local.json"));
  if (settingsFile) files.push(resolve(cwd, settingsFile));

  const managed =
    process.env.CC_MANAGED_SETTINGS ||
    (process.platform === "win32"
      ? join(
          process.env.ProgramData ||
            process.env.PROGRAMDATA ||
            "C:\\ProgramData",
          "ChainlessChain",
          "managed-settings.json",
        )
      : "/etc/chainlesschain/managed-settings.json");
  files.push(resolve(managed));
  if (mcpConfig) files.push(resolve(cwd, mcpConfig));
  if (projectMcp) {
    files.push(join(gitRoot || cwd, ".mcp.json"));
  }
  if (bundle) files.push(resolve(cwd, bundle));

  const unique = [...new Set(files.map((file) => canonicalPath(file)))].sort();
  return unique.map((file) => describeBackgroundConfigSource(file));
}

/** Return a credential-free representation of a base URL. */
export function sanitizeBackgroundBaseUrl(value) {
  const original = scalar(value, 8192);
  if (!original) return { value: null, redacted: false };
  try {
    const url = new URL(original);
    if (url.protocol !== "http:" && url.protocol !== "https:") {
      return { value: null, redacted: true };
    }
    const redacted = Boolean(
      url.username || url.password || url.search || url.hash,
    );
    url.username = "";
    url.password = "";
    url.search = "";
    url.hash = "";
    return { value: url.toString(), redacted };
  } catch {
    return { value: null, redacted: true };
  }
}

function splitLongOption(token) {
  const index = token.indexOf("=");
  return index === -1
    ? { name: token, inline: null }
    : { name: token.slice(0, index), inline: token.slice(index + 1) };
}

function emptyParsedProfile(cwd, worktree, governance) {
  return {
    version: BACKGROUND_LAUNCH_PROFILE_VERSION,
    command: "agent",
    llm: {
      provider: null,
      model: null,
      baseUrl: null,
      baseUrlRedacted: false,
      visionModel: null,
      fallbackModels: [],
    },
    tools: { allowed: null, disallowed: [] },

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  mkdirSync,
  mkdtempSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  assessBackgroundLaunchProfileCompatibility,
  buildArgvFromBackgroundLaunchProfile,
  canonicalBackgroundLaunchProfileJson,
  captureBackgroundLaunchProfile,
  fingerprintBackgroundLaunchProfile,
  refreshBackgroundLaunchProfileSources,
  normalizeBackgroundLaunchProfile,
  sanitizeBackgroundBaseUrl,
  stripBackgroundLaunchSecrets,
  verifyBackgroundLaunchProfileSources,
} from "../../src/lib/background-launch-profile.js";

let dir;
let previousHome;

beforeEach(() => {
  dir = realpathSync.native(mkdtempSync(join(tmpdir(), "cc-bg-profile-")));
  previousHome = process.env.CHAINLESSCHAIN_HOME;
  process.env.CHAINLESSCHAIN_HOME = join(dir, "home");
  mkdirSync(process.env.CHAINLESSCHAIN_HOME, { recursive: true });
});

afterEach(() => {
  if (previousHome === undefined) delete process.env.CHAINLESSCHAIN_HOME;
  else process.env.CHAINLESSCHAIN_HOME = previousHome;
  rmSync(dir, { recursive: true, force: true });
});

function capture(argv) {
  return captureBackgroundLaunchProfile({
    argv,
    cwd: dir,
    governance: {
      permissionMode: "manual",
      resourceBudget: { maxTurns: 12, maxCostUsd: 4.5 },
    },
  });
}

describe("background launch profile", () => {
  it("refuses to capture an ephemeral profile that resume cannot preserve", () => {
    expect(() =>
      capture(["agent", "--ephemeral", "--session", "ephemeral-session"]),
    ).toThrowError(
      expect.objectContaining({ code: "BACKGROUND_EPHEMERAL_UNSUPPORTED" }),
    );
  });

  it("captures a versioned effective envelope without prompt or credentials", () => {
    const settings = join(dir, "settings.json");
    const mcp = join(dir, "mcp.json");
    const bundle = join(dir, "bundle");
    const extra = join(dir, "extra");
    writeFileSync(
      settings,
      JSON.stringify({ env: { PRIVATE_TOKEN: "settings-env-secret" } }),
    );
    writeFileSync(mcp, JSON.stringify({ bearer: "mcp-secret" }));
    mkdirSync(bundle);
    writeFileSync(join(bundle, "AGENTS.md"), "bundle-private-text");
    mkdirSync(extra);

    const profile = capture([
      "agent",
      "fix",
      "the",
      "bug",
      "--provider",
      "openai",
      "--model",
      "gpt-test",
      "--base-url",
      "https://user:password@example.test/v1?api_key=query-secret#fragment",
      "--api-key",
      "argv-api-secret",
      "--allowed-tools",
      "read_file,run_shell",
      "--disallowed-tools",
      "delete_file",
      "--permission-mode",
      "acceptEdits",
      "--sandbox",
      "sandbox-image",
      "--sandbox-mode",
      "strict",
      "--mcp-config",
      mcp,
      "--strict-mcp-config",
      "--settings",
      settings,
      "--bundle",
      bundle,
      "--add-dir",
      extra,
      "--max-turns",
      "8",
      "--max-budget-usd",
      "2.25",
      "--system-prompt",
      "system-prompt-secret",
      "-p",
      "task-prompt-secret",
    ]);

    expect(profile).toMatchObject({
      version: 1,
      command: "agent",
      llm: {
        provider: "openai",
        model: "gpt-test",
        baseUrl: "https://example.test/v1",
        baseUrlRedacted: true,
      },
      tools: {
        allowed: ["read_file", "run_shell"],
        disallowed: ["delete_file"],
      },
      permission: { mode: "acceptEdits" },
      sandbox: { enabled: true, image: "sandbox-image", mode: "strict" },
      mcp: { configFile: mcp, strict: true },
      settings: { file: settings },
      plugins: { bundle },
      workspace: { cwd: dir, addDirs: [extra] },
      budget: { maxTurns: 8, maxCostUsd: 2.25 },
      credentials: { apiKey: "external" },
    });
    expect(profile.omitted).toEqual(
      expect.arrayContaining(["apiKey", "systemPrompt", "taskPrompt"]),
    );
    expect(profile.configuration.sources).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ path: settings, kind: "file" }),
        expect.objectContaining({ path: mcp, kind: "file" }),
        expect.objectContaining({ path: bundle, kind: "directory" }),
      ]),
    );

    const persisted = JSON.stringify(profile);
    for (const secret of [
      "password",
      "query-secret",
      "argv-api-secret",
      "system-prompt-secret",
      "task-prompt-secret",
      "settings-env-secret",
      "mcp-secret",
      "bundle-private-text",
    ]) {
      expect(persisted).not.toContain(secret);
    }
  });

  it("does not persist parent-only background worktree switches", () => {
    for (const flag of ["--worktree", "--no-worktree"]) {
      const profile = capture(["agent", "--background", flag, "-p", "do work"]);
      expect(profile.omitted).not.toContain(`option:${flag.slice(2)}`);
      const rebuilt = buildArgvFromBackgroundLaunchProfile(profile);
      expect(rebuilt).not.toContain("--worktree");
      expect(rebuilt).not.toContain("--no-worktree");
      expect(rebuilt).not.toContain("--background");
    }
  });

  it("uses canonical JSON for stable fingerprints and changes on policy drift", () => {
    const first = capture([
      "agent",
      "task one",
      "--model",
      "m1",
      "--allowed-tools",
      "run_shell,read_file",
      "--disallowed-tools",
      "write_file,delete_file",
    ]);
    const reordered = capture([
      "agent",
      "another task",
      "--disallowed-tools",
      "delete_file,write_file",
      "--allowed-tools",
      "read_file,run_shell",
      "--model",
      "m1",
    ]);

    expect(canonicalBackgroundLaunchProfileJson(first)).toBe(
      canonicalBackgroundLaunchProfileJson(reordered),
    );
    expect(fingerprintBackgroundLaunchProfile(first)).toBe(
      fingerprintBackgroundLaunchProfile(reordered),
    );

    const changedModel = structuredClone(first);
    changedModel.llm.model = "m2";
    const loosenedPermission = structuredClone(first);
    loosenedPermission.permission.dangerousBypass = true;
    const loosenedBudget = structuredClone(first);
    loosenedBudget.budget.maxTurns = null;
    const loosenedMode = structuredClone(first);
    loosenedMode.permission.mode = "bypassPermissions";
    const loosenedTools = structuredClone(first);
    loosenedTools.tools.allowed = null;
    const fallbackOrderOne = capture([
      "agent",
      "task",
      "--fallback-model",
      "first,second",
    ]);
    const fallbackOrderTwo = capture([
      "agent",
      "task",
      "--fallback-model",
      "second,first",
    ]);
    for (const changed of [changedModel, loosenedPermission, loosenedBudget]) {
      expect(fingerprintBackgroundLaunchProfile(changed)).not.toBe(
        fingerprintBackgroundLaunchProfile(first),
      );
    }

    expect(
      assessBackgroundLaunchProfileCompatibility(first, changedModel),
    ).toMatchObject({ compatible: false, reasons: ["model-changed"] });
    expect(
      assessBackgroundLaunchProfileCompatibility(first, loosenedPermission)
        .reasons,
    ).toContain("permission-bypass-enabled");
    expect(
      assessBackgroundLaunchProfileCompatibility(first, loosenedBudget).reasons,
    ).toContain("budget-loosened");
    expect(
      assessBackgroundLaunchProfileCompatibility(first, loosenedMode).reasons,
    ).toContain("permission-mode-loosened");
    expect(
      assessBackgroundLaunchProfileCompatibility(first, loosenedTools).reasons,
    ).toContain("tool-policy-loosened");
    expect(fingerprintBackgroundLaunchProfile(fallbackOrderOne)).not.toBe(
      fingerprintBackgroundLaunchProfile(fallbackOrderTwo),
    );
  });

  it("rebuilds resumable argv while keeping redacted values out", () => {
    const profile = capture([
      "agent",
      "do not persist me",
      "--provider",
      "openai",
      "--model",
      "gpt-test",
      "--api-key=top-secret",
      "--permission-mode",
      "plan",
      "--sandbox-mode",
      "strict",
      "--allowed-tools",
      "read_file",
      "--max-turns",
      "5",
    ]);
    const argv = buildArgvFromBackgroundLaunchProfile(profile);

    expect(argv).toEqual(
      expect.arrayContaining([
        "agent",
        "--provider",
        "openai",
        "--model",
        "gpt-test",
        "--permission-mode",
        "plan",
        "--sandbox-mode",
        "strict",
        "--max-turns",
        "5",
      ]),
    );
    expect(JSON.stringify(argv)).not.toContain("top-secret");
    expect(JSON.stringify(argv)).not.toContain("do not persist me");
    expect(argv).not.toContain("--api-key");
  });

  it("detects configuration content changes and can refresh explicitly", () => {
    const settings = join(dir, "settings.json");
    writeFileSync(settings, JSON.stringify({ model: "one" }));
    const profile = capture(["agent", "task", "--settings", settings]);
    expect(verifyBackgroundLaunchProfileSources(profile)).toMatchObject({
      valid: true,
      issues: [],
    });

    writeFileSync(settings, JSON.stringify({ model: "two" }));
    const check = verifyBackgroundLaunchProfileSources(profile);
    expect(check.valid).toBe(false);
    expect(check.issues).toEqual([`configuration-source-changed:${settings}`]);
    const refreshed = refreshBackgroundLaunchProfileSources(profile);
    expect(verifyBackgroundLaunchProfileSources(refreshed).valid).toBe(true);
    expect(fingerprintBackgroundLaunchProfile(refreshed)).not.toBe(
      fingerprintBackgroundLaunchProfile(profile),
    );
  });

  it("preserves an explicit empty tool allowlist in resumed argv", () => {
    const profile = capture(["agent", "--allowed-tools", ""]);
    expect(profile.tools.allowed).toEqual([]);
    const argv = buildArgvFromBackgroundLaunchProfile(profile);
    expect(
      argv.slice(
        argv.indexOf("--allowed-tools"),
        argv.indexOf("--allowed-tools") + 2,
      ),
    ).toEqual(["--allowed-tools", ""]);
    expect(capture(argv).tools.allowed).toEqual([]);
  });

  it.each([
    ["permission", "mode", "corrupted-mode"],
    ["sandbox", "mode", "corrupted-sandbox"],
    ["budget", "maxCostUsd", -1],
    ["budget", "maxTurns", -1],
  ])(
    "rejects a malformed persisted %s.%s instead of relaxing it",
    (section, key, value) => {
      const profile = capture(["agent"]);
      profile[section][key] = value;
